package demo.brain;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class KnowledgeCases {
 private final Store s;public KnowledgeCases(Store s){this.s=s;}
 public List<Map<String,Object>> list(){var me=Access.current();var rows=s.db.queryForList("SELECT * FROM skills WHERE (?=TRUE OR status='APPROVED' OR created_by=?) ORDER BY created_at DESC,id",me.admin(),me.id());for(var row:rows)row.put("assetIds",s.db.queryForList("SELECT asset_id FROM skill_assets WHERE skill_id=? ORDER BY asset_id",String.class,row.get("id")));return rows;}
 public Object create(Map<String,Object> b){return s.tx(()->{String id=Store.id("SKL-");var fields=fields(b);var assets=assets(b);s.db.update("INSERT INTO skills(id,type,title,status,conditions,checks,solution,cautions,created_at,source_kind,symptoms,created_by,source_provider,simulated) VALUES (?,?,?,'DRAFT',?,?,?,?,?,'MANUAL_ENTRY',?,?,?,TRUE)",id,fields.get("type"),fields.get("title"),fields.get("conditions"),fields.get("checks"),fields.get("solution"),fields.get("cautions"),Store.now(),fields.get("symptoms"),Access.actor(),"MANUAL_ENTRY");link(id,assets);s.audit(null,Access.actor(),"SKILL_MANUAL_CREATED",Map.of("skillId",id));return s.one("SELECT * FROM skills WHERE id=?",id);});}
 private Map<String,String> fields(Map<String,Object> b){var result=new LinkedHashMap<String,String>();for(String f:List.of("title","type","conditions","symptoms","checks","solution","cautions")){String v=Objects.toString(b.get(f),"");Harness.text(v,f.equals("title")?200:6000,f);result.put(f,v);}if(!JevDecision.TYPES.contains(result.get("type")))throw new IllegalArgumentException("장애 유형을 확인하세요.");return result;}
 private List<String> assets(Map<String,Object> b){if(!(b.get("assetIds") instanceof List<?> ids)||ids.size()>52)throw new IllegalArgumentException("관련 자산 목록이 필요합니다.");var result=new TreeSet<String>();for(var id:ids){if(!(id instanceof String))throw new IllegalArgumentException("자산 ID를 확인하세요.");s.one("SELECT id FROM assets WHERE id=?",id);result.add(id.toString());}return List.copyOf(result);}
 private void link(String id,List<String> assets){s.db.update("DELETE FROM skill_assets WHERE skill_id=?",id);for(var asset:assets)s.db.update("INSERT INTO skill_assets VALUES (?,?)",id,asset);}
 public void editable(Map<String,Object> skill){if(!Access.current().admin()&&!Access.actor().equals(skill.get("created_by")))throw Access.denied();if(!"DRAFT".equals(skill.get("status")))throw new IllegalStateException("임시 저장 상태만 편집할 수 있습니다.");}
 public Object edit(String id,Map<String,Object> b){return s.tx(()->{var before=s.one("SELECT * FROM skills WHERE id=? FOR UPDATE",id);editable(before);if(!"MANUAL_ENTRY".equals(before.get("source_kind")))throw Access.denied();if(!(b.get("revision") instanceof Number n)||n.intValue()!=((Number)before.get("revision")).intValue())throw new IllegalStateException("지식 버전이 변경되었습니다.");var f=fields(b);var a=assets(b);String reason=Objects.toString(b.get("reason"),"");Harness.text(reason,1000,"수정 사유");before.put("assetIds",s.db.queryForList("SELECT asset_id FROM skill_assets WHERE skill_id=? ORDER BY asset_id",String.class,id));s.db.update("UPDATE skills SET title=?,type=?,conditions=?,symptoms=?,checks=?,solution=?,cautions=?,revision=revision+1 WHERE id=?",f.get("title"),f.get("type"),f.get("conditions"),f.get("symptoms"),f.get("checks"),f.get("solution"),f.get("cautions"),id);link(id,a);var after=s.one("SELECT * FROM skills WHERE id=?",id);after.put("assetIds",a);s.db.update("INSERT INTO skill_revisions(skill_id,revision,action,actor,reason,before_json,after_json,created_at) VALUES (?,?,?,?,?,?,?,?)",id,after.get("revision"),"EDIT",Access.actor(),reason,s.encode(before),s.encode(after),Store.now());s.audit(null,Access.actor(),"SKILL_EDIT",Map.of("skillId",id));return after;});}
 public Object submit(String id,Map<String,Object> b){return s.tx(()->{var row=s.one("SELECT * FROM skills WHERE id=? FOR UPDATE",id);editable(row);if(!"MANUAL_ENTRY".equals(row.get("source_kind")))throw new IllegalStateException("직접 등록한 초안만 승인 요청할 수 있습니다.");if(!(b.get("revision") instanceof Number n)||n.intValue()!=((Number)row.get("revision")).intValue())throw new IllegalStateException("지식 버전이 변경되었습니다.");s.db.update("UPDATE skills SET status='PENDING',submitted_at=?,revision=revision+1 WHERE id=?",Store.now(),id);s.audit(null,Access.actor(),"SKILL_SUBMITTED",Map.of("skillId",id));return s.one("SELECT * FROM skills WHERE id=?",id);});}
 public Object revisions(String id){var row=s.one("SELECT * FROM skills WHERE id=?",id);if(!Access.current().admin()&&!Access.actor().equals(row.get("created_by")))throw Access.denied();return s.db.queryForList("SELECT * FROM skill_revisions WHERE skill_id=? ORDER BY revision DESC",id);}
 public Map<String,Object> search(Map<String,Object> incident){
  String type=Objects.toString(incident.get("type"),""),asset=Objects.toString(incident.get("asset_id"),"");var target=s.db.queryForList("SELECT * FROM assets WHERE id=?",asset);String system=target.isEmpty()?"":Objects.toString(target.get(0).get("system_id"),asset);
  Set<String> historic=new HashSet<>();if(incident.containsKey("observations"))for(var old:new SimilarIncidents(s).find(incident))historic.add(old.get("id").toString());
  var links=s.db.queryForList("SELECT sa.skill_id,sa.asset_id,a.system_id FROM skill_assets sa JOIN assets a ON a.id=sa.asset_id");var ranked=new ArrayList<Map<String,Object>>();
  for(var skill:s.db.queryForList("SELECT * FROM skills WHERE status='APPROVED' ORDER BY id")){int score=0;var reasons=new ArrayList<String>();if(type.equals(skill.get("type"))){score+=40;reasons.add("장애 유형 일치");}
   var own=links.stream().filter(x->skill.get("id").equals(x.get("skill_id"))).toList();if(!asset.isBlank()&&own.stream().anyMatch(x->asset.equals(x.get("asset_id")))){score+=35;reasons.add("장애 발생 자산에 연결된 지식");}if(!system.isBlank()&&own.stream().anyMatch(x->system.equals(x.get("asset_id"))||system.equals(x.get("system_id")))){score+=20;reasons.add("관련 업무 시스템 일치");}if(historic.contains(Objects.toString(skill.get("incident_id"),""))){score+=5;reasons.add("유사 장애의 해결 지식");}if(score>0){skill.put("matchScore",score);skill.put("matchReasons",reasons);skill.put("scoreKind","RULE_MATCH_NOT_PROBABILITY");ranked.add(skill);}}
  ranked.sort(Comparator.<Map<String,Object>>comparingInt(x->-((Number)x.get("matchScore")).intValue()).thenComparing(x->x.get("id").toString()));
  return Map.of("skills",ranked.stream().limit(20).toList(),"manuals",s.db.queryForList("SELECT * FROM manuals WHERE type=? ORDER BY id",type),"approvedOnly",true,"scoreKind","RULE_MATCH_NOT_PROBABILITY");
 }
 public Object assetContext(String id){var asset=s.one("SELECT * FROM assets WHERE id=?",id);var components=s.db.queryForList("SELECT * FROM assets WHERE system_id=? ORDER BY id",id);String system=Objects.toString(asset.get("system_id"),id);var skills=s.db.queryForList("SELECT DISTINCT k.* FROM skills k JOIN skill_assets sa ON sa.skill_id=k.id JOIN assets a ON a.id=sa.asset_id WHERE k.status='APPROVED' AND (a.id=? OR a.system_id=? OR a.id=?) ORDER BY k.id",id,id,system);
  var history=s.db.queryForList("SELECT i.id,i.title,i.type,i.status,i.notes,i.prevention,i.created_at FROM incidents i JOIN assets a ON a.id=i.asset_id WHERE i.deleted_at IS NULL AND (a.id=? OR a.system_id=?) ORDER BY i.created_at DESC LIMIT 20",id,id);var counts=s.db.queryForList("SELECT i.type,COUNT(*) total FROM incidents i JOIN assets a ON a.id=i.asset_id WHERE i.deleted_at IS NULL AND (a.id=? OR a.system_id=?) GROUP BY i.type ORDER BY total DESC",id,id);
  var types=new HashSet<String>();history.forEach(x->types.add(x.get("type").toString()));skills.forEach(x->types.add(x.get("type").toString()));return Map.of("asset",asset,"components",components,"dependencies",s.db.queryForList("SELECT * FROM dependencies WHERE source_id=? OR target_id=?",id,id),"skills",skills,"incidents",history,"types",counts,"manuals",s.db.queryForList("SELECT * FROM manuals ORDER BY id").stream().filter(x->types.contains(x.get("type"))).toList(),"approvedOnly",true);
 }
}
